import{at as e,it as t,n,vt as r}from"./chunks/framework.DbV_8hbX.js";import"./chunks/assets.ByxXdwmG.js";var i=JSON.parse(`{"title":"Jev connection settings and usage","description":"","frontmatter":{},"headers":[],"relativePath":"en/guides/jev.md","filePath":"en/guides/jev.md","lastUpdated":1794405696000}`),a={name:`en/guides/jev.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="jev-connection-settings-and-usage" tabindex="-1">Jev connection settings and usage <a class="header-anchor" href="#jev-connection-settings-and-usage" aria-label="Permalink to “Jev connection settings and usage”">​</a></h1><p>Select the target site and open &quot;Jev connection (「Jev連携」)&quot; in the left menu. Only site admins and superusers can use it. Key settings and usage records are not shown to editors or viewers.</p><h2 id="set-the-key-for-each-site" tabindex="-1">Set the key for each site <a class="header-anchor" href="#set-the-key-for-each-site" aria-label="Permalink to “Set the key for each site”">​</a></h2><p>A Jev API key is registered per site ID. An instance-wide key is not used. New sites, and sites that used a shared key before, show &quot;API key not set (「APIキー未設定」)&quot;.</p><table tabindex="0"><thead><tr><th>Key to use</th><th>Behavior</th></tr></thead><tbody><tr><td>Site-only key</td><td>Uses the Jev API key saved for this site ID</td></tr><tr><td>Stop using Jev</td><td>Stops Jev judgments for this site and deletes the saved key</td></tr></tbody></table><ol><li>Choose &quot;Site-only key (「サイト専用キー」)&quot;.</li><li>Enter it in &quot;New site-only API key (「新しいサイト専用APIキー」)&quot;.</li><li>Press &quot;Save Jev connection settings (「Jev接続設定を保存」)&quot; and confirm. Verify with your passkey if asked.</li></ol><p>A saved value is never shown again. When you open it again the field is empty and only &quot;Saved&quot; is shown. If a site-only key already exists, saving with the field empty keeps the current value. Entering a new value replaces it. Saving doesn&#39;t connect to Jev, check validity or incur charges.</p><p>Saving a site-only key requires the environment administrator to complete the <a href="./../operations/jev-keys">initial setup of the encryption key</a>. If it isn&#39;t set up, a message tells you so.</p><div class="warning custom-block"><p class="custom-block-title">Switching the connection mode</p><p>Changing to &quot;Stop using&quot; deletes the saved site key. To go back, enter the key again. It does not revoke the key on the Jev side.</p></div><p>If the key is not set, revoked or can&#39;t be decrypted, judgment is held. The keys of other sites are not used. Requests already in progress before the key change can&#39;t be cancelled.</p><p>The screen below is an example with test settings. No real API key is shown.</p><p><img src="/jev-personalization/images/jev-connection.png" alt="Connection settings for a site-only key" width="1280" height="928"></p><h2 id="notices-about-the-setup-status" tabindex="-1">Notices about the setup status <a class="header-anchor" href="#notices-about-the-setup-status" aria-label="Permalink to “Notices about the setup status”">​</a></h2><p>The admin console for the selected site shows what is not set or stopped, and where to fix it. Editors and viewers can also see what is missing, but only site admins and superusers can register or change keys and view usage records.</p><ul><li><strong>API key not set</strong>: register a key from &quot;Jev connection&quot; for this site.</li><li><strong>No encryption setup, or the key can&#39;t be read</strong>: ask the environment administrator to check JEV_KEYRING.</li><li><strong>Jev is stopped</strong>: to resume, enter a site-only key again.</li><li><strong>Metadata sending is disabled, or no campaign is being delivered</strong>: check the site settings and the campaign list.</li></ul><p>The status updates when you switch sites, reload the page or save. This notice alone can&#39;t confirm that the SDK tag is placed or that users have consented. Check those from &quot;Verification&quot;. A &quot;saved&quot; indicator for the key doesn&#39;t guarantee validity or balance on the Jev side. No Jev request is made to check them. A judgment settled by the URL alone works without a key, even for a campaign that contains Jev conditions. If an unsettled Jev condition remains, the site needs a registered key. Preview&#39;s fixed-value judgment does not connect to the real Jev.</p><p><img src="/jev-personalization/images/site-readiness.png" alt="An example where the missing settings are also shown to viewers. Ask a site admin to change the key." width="390" height="1021"></p><h2 id="view-usage" tabindex="-1">View usage <a class="header-anchor" href="#view-usage" aria-label="Permalink to “View usage”">​</a></h2><p>Open &quot;Usage (「利用状況」)&quot;, choose the past 7, 30 or 90 days and press &quot;Refresh (「更新」)&quot;. Totals are by UTC day. It shows daily counts, plus the latest 100 results, model names, HTTP status, latency and key type. Records from the retired shared key are shown as &quot;Shared key (retired)&quot;, and new calls use only site-only keys. This is the whole site&#39;s record, including before and after key changes. There is no automatic polling.</p><table tabindex="0"><thead><tr><th>Display</th><th>Meaning</th></tr></thead><tbody><tr><td>Calls started</td><td>The number of times the start of a Jev API call was recorded</td></tr><tr><td>Successful responses</td><td>The number of times the HTTP response and basic data format were normal. Not the number that met the display conditions</td></tr><tr><td>Errors</td><td>HTTP failures, timeouts, communication failures and malformed response formats</td></tr><tr><td>Result unconfirmed</td><td>Records whose result isn&#39;t settled because they are in progress, interrupted or failed to save</td></tr></tbody></table><p>Not every decision request from a browser reaches Jev. Unmet conditions, exceeding the budget, a missing key, a stop, fixed judgments in Preview/local-review and forced previews before delivery are not counted. History from before this feature was introduced is not shown either.</p><p>The counts, results, models and latency in the example screen are artificial data created to verify the UI. They are not measurements from Jev.</p><p><img src="/jev-personalization/images/jev-usage.png" alt="An example of the Jev usage screen" width="1280" height="1306"></p><h2 id="counts-versus-billing" tabindex="-1">Counts versus billing <a class="header-anchor" href="#counts-versus-billing" aria-label="Permalink to “Counts versus billing”">​</a></h2><p>A record is made before sending starts and its result is updated after the response. An interruption in between can leave a start row even though nothing was actually sent, or leave a result unconfirmed even though it was sent. It is not a counter that guarantees the number of requests Jev received, the number billed or the amount.</p><p><strong>Check billing and consumption on the Jev (TypeSafe) side.</strong> Whether a failed request is billed also follows the provider&#39;s rules. A successful response doesn&#39;t mean a purchase or campaign success, and latency is Jev&#39;s HTTP processing time, not the total time until the display.</p><p>The cost limit and concurrency are shared across the whole instance, even when site-only keys are used. A per-site budget limit is not part of this release.</p><h2 id="what-is-not-recorded" tabindex="-1">What is not recorded <a class="header-anchor" href="#what-is-not-recorded" aria-label="Permalink to “What is not recorded”">​</a></h2><p>Key values or fragments, visitor IDs, IPs, URLs, history, state, questions, answers, probabilities and request/response bodies are not kept. Only operational metadata about the call is stored. Records are shown for up to 90 days, and old rows are deleted when the feature is used or viewed. Records inside backups are managed under a separate retention policy.</p><p>With Preview&#39;s fixed judgment, entering a key doesn&#39;t confirm actual validity or the connection to Jev, and the usage count doesn&#39;t increase. If you want to try a real connection, check with the environment administrator and do it separately, as a request that will be billed.</p>`,30)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};